commands.cmd:
I="${RR:?}/mcp-inspector-strict-control"; rm -rf "$I" && mkdir -p "$I" && cat > "$I/fixture_server.py" <<'PYEOF'
import json
import sys


def send(obj):
    sys.stdout.write(json.dumps(obj) + "\n")
    sys.stdout.flush()


for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        msg = json.loads(line)
    except json.JSONDecodeError:
        continue
    method, msg_id = msg.get("method"), msg.get("id")
    if method == "initialize":
        send({"jsonrpc": "2.0", "id": msg_id, "result": {
            "protocolVersion": (msg.get("params") or {}).get("protocolVersion", "2025-06-18"),
            "capabilities": {"tools": {}},
            "serverInfo": {"name": "nsr-schema-unportable-fixture", "version": "0.1.0"},
        }})
    elif method == "tools/list":
        send({"jsonrpc": "2.0", "id": msg_id, "result": {"tools": [{
            "name": "nsr_bad_schema_tool",
            "description": "Owned fixture tool with a bare boolean property schema.",
            "inputSchema": {"type": "object", "properties": {"x": True}},
        }]}})
    elif msg_id is not None:
        send({"jsonrpc": "2.0", "id": msg_id, "error": {"code": -32601, "message": "method not found"}})
PYEOF
python3 -c "import json,sys;json.dump({'mcpServers':{'nsrfixture':{'command':'python3','args':[sys.argv[1]]}}},open(sys.argv[2],'w'))" "$I/fixture_server.py" "$I/servers.json" && MCP_CLIENT_CONFIG_PATH="$I/client.json" mcp-inspector --cli --config "$I/servers.json" --server nsrfixture --method tools/list --strict --format json --stored-auth-only > "$I/list.json" 2> "$I/list.err"; rc=$?; echo "owned fixture MCP server with one tool whose inputSchema is type object properties x true (bare boolean property schema): tools/list --strict exit=$rc, expected 6 (schema_unportable)"; grep -o '"code":"schema_unportable"[^}]*}' "$I/list.err"; rm -rf "$I"; test "$rc" -eq 6
